  let dx = sx + params.offsetX;
  let dy = sy + params.offsetY;

  if (dx < 0 || dy < 0 || dx >= i32(params.dstW) || dy >= i32(params.dstH)) { return; }

  let srcIdx = u32(sy) * params.srcW + u32(sx);
